frappe.ui.form.on('Employee', {
    refresh:function(frm){
        toggle_child_table_access(frm);
    },
    validate: function(frm) {
        const table = frm.doc.custom_months_for_bonus || [];

        // Create a map to track months per fiscal year
        const fy_map = {};

        for (let row of table) {
            const fy = row.fiscal_year;
            const month = row.month;

            if (!fy || !month) {
                frappe.throw(__('Each row in Bonus Months must have both Fiscal Year and Month filled.'));
            }

            // Initialize array for the fiscal year if not already
            if (!fy_map[fy]) {
                fy_map[fy] = [];
            }

            // Check for duplicate month in the same fiscal year
            if (fy_map[fy].includes(month)) {
                frappe.throw(
                    __('Duplicate month "{0}" found for fiscal year "{1}" in Bonus Months table.', [month, fy])
                );
            }

            fy_map[fy].push(month);

            // Check for more than 2 months per fiscal year
            if (fy_map[fy].length > 2) {
                frappe.throw(
                    __('Only 2 bonus months allowed per fiscal year. Fiscal Year "{0}" has more.', [fy])
                );
            }
        }
    }
});

function toggle_child_table_access(frm){
    if(frm.doc.custom_months_for_bonus.length == 2 && !frappe.user.has_role("HR Manager") ){
       frm.set_df_property("custom_months_for_bonus", "read_only", 1)
    }
    else{
        frm.set_df_property("custom_months_for_bonus", "read_only", 0)
    }

}

function set_place_of_supply_and_tax(frm) {
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Customer",
            name: frm.doc.customer
        },
        callback: function(r) {
            if (r.message) {
                let customer_group = r.message.customer_group;
                let gst_category = r.message.gst_category;

                if (customer_group === "CQI" && gst_category === "Unregistered") {
                    // Wait till address loads
                    setTimeout(() => {
                        frm.set_value("place_of_supply", "29-Karnataka");
                        frm.set_value("taxes_and_charges", "Output GST In-state - EEPL");  // Update template name if needed
                    }, 800); // Delay ensures ERPNext's internal autofill finishes
                }
            }
        }
    });
}

