frappe.ui.form.on('Stock Entry', {
  // on form load / refresh
  refresh(frm) {
    _compute_fg_and_loss(frm);
  },

  // when you toggle the Cropster flag
  custom_cropster_entry(frm) {
    _compute_fg_and_loss(frm);
  },

  // when you change the loss percentage
  process_loss_percentage(frm) {
    _compute_fg_and_loss(frm);
  },

  // when you edit the “after loss” qty
  custom_qty_after_loss(frm) {
    _compute_fg_and_loss(frm);
  }
});

function _compute_fg_and_loss(frm) {
  console.log(
    '[Cropster] ▶️ compute FG & Loss:',
    'afterLoss=', frm.doc.custom_qty_after_loss,
    'lossPct=', frm.doc.process_loss_percentage,
    'flag=', frm.doc.custom_cropster_entry
  );

  // only when Cropster entry is on, loss% > 0, and after-loss is present
  if (
    frm.doc.custom_cropster_entry === 1 &&
    frm.doc.process_loss_percentage > 0 &&
    frm.doc.custom_qty_after_loss > 0
  ) {
    // 1) Read inputs
    const afterQty = flt(frm.doc.custom_qty_after_loss, 6);
    const lossPct  = flt(frm.doc.process_loss_percentage, 6);
    const factor   = (100 - lossPct) / 100;   // e.g. 0.87

    // 2) Back-calculate Finished Good Qty
    const fgQty    = flt(afterQty / factor, 2);

    // 3) Compute loss quantity = FG × lossPct / 100
    const lossQty  = flt(fgQty * lossPct / 100, 2);

    console.log(
      '[Cropster] → fg_completed_qty =', fgQty,
      ', process_loss_qty =', lossQty
    );

    // 4) Write values back
    frm.set_value('fg_completed_qty', fgQty);
    frm.set_value('process_loss_qty', lossQty);
    frm.refresh_field('fg_completed_qty');
    frm.refresh_field('process_loss_qty');

    // 5) Show a friendly alert
    frappe.show_alert({
      message: `Finished Good: ${fgQty} | Loss Qty: ${lossQty}`,
      indicator: 'green'
    });

  } else {
    console.log('[Cropster] skipping compute (conditions not met)');
  }
}

