// ──────────────────────────────────────────────────────────────────────────
// Stock Entry → qty = custom_qty_before_loss × (1 – custom_loss/100)
// Only if parent custom_apply_loss == 1; otherwise nothing runs.
// ──────────────────────────────────────────────────────────────────────────
(function() {
  // Round to 6 decimals
  function round6(val) {
    return Math.round((val + Number.EPSILON) * 1e6) / 1e6;
  }

  // Recompute one row (bail out if parent flag is off)
  function recalc_row(frm, cdt, cdn) {
    if (!frm.doc.custom_apply_loss) return;
    const row = locals[cdt][cdn];
    const before = parseFloat(row.custom_qty_before_loss) || 0;
    const lossPct = parseFloat(row.custom_loss) || 0;
    const newQty = round6(before * (1 - lossPct / 100));
    frappe.model.set_value(cdt, cdn, 'qty', newQty);
    frm.refresh_field('items');
  }

  // Bind or unbind live-input handlers based on parent flag
  function bind_handlers(frm) {
    const grid = frm.fields_dict.items.grid.wrapper;

    // remove previous bindings
    grid.off('.loss_calc');

    if (!frm.doc.custom_apply_loss) {
      console.log("🛑 Loss script disabled (custom_apply_loss = 0)");
      return;
    }

    console.log("✅ Loss script enabled (custom_apply_loss = 1)");

    // As-you-type for Before-Loss
    grid.on(
      'input.loss_calc',
      'input[data-fieldname="custom_qty_before_loss"]',
      (_, el) => {
        const cdn = $(el)
          .closest('[data-doctype="Stock Entry Detail"]')
          .attr('data-name');
        recalc_row(frm, 'Stock Entry Detail', cdn);
      }
    );

    // As-you-type for Loss%
    grid.on(
      'input.loss_calc',
      'input[data-fieldname="custom_loss"]',
      (_, el) => {
        const cdn = $(el)
          .closest('[data-doctype="Stock Entry Detail"]')
          .attr('data-name');
        recalc_row(frm, 'Stock Entry Detail', cdn);
      }
    );
  }

  // ────────────────────────────────────────────────────────────────────────
  frappe.ui.form.on('Stock Entry', {
    refresh(frm) {
      // (Re)bind handlers every time form refreshes
      bind_handlers(frm);

      // If enabled, do initial calculate for saved rows
      if (frm.doc.custom_apply_loss) {
        (frm.doc.items || []).forEach(row =>
          recalc_row(frm, 'Stock Entry Detail', row.name)
        );
      }
    },

    // Toggle handler for the parent checkbox
    custom_apply_loss(frm) {
      console.log(
        "🔄 custom_apply_loss toggled →",
        frm.doc.custom_apply_loss
      );
      frm.refresh();
    }
  });

  // Also catch blur/change in child fields
  frappe.ui.form.on('Stock Entry Detail', {
    custom_qty_before_loss(frm, cdt, cdn) {
      recalc_row(frm, cdt, cdn);
    },
    custom_loss(frm, cdt, cdn) {
      recalc_row(frm, cdt, cdn);
    }
  });
})();

