frappe.ui.form.on('Sales Order', {
    refresh: function (frm) {
        // Re-run when taxes are re-rendered
        frm.fields_dict['taxes'].grid.wrapper.on('DOMSubtreeModified', function () {
            hide_standard_column();
        });

        // Also try on initial load
        setTimeout(hide_standard_column, 1000);

        function hide_standard_column() {
            // Find the "Standard" header and get its column index
            $("div.tax-breakup table").each(function () {
                const table = $(this);
                table.find("thead th").each(function (index) {
                    if ($(this).text().trim() === "Standard") {
                        const colIndex = index + 1; // nth-child is 1-based
                        // Hide both header and all rows for that column
                        table.find("tr").each(function () {
                            $(this).find(`th:nth-child(${colIndex}), td:nth-child(${colIndex})`).hide();
                        });
                    }
                });
            });
        }
    }
});

