// Script for Purchase Invoice
frappe.ui.form.on('Purchase Invoice', {
    onload(frm) {
        // Clear the Payment Schedule table before adding new rows
        frm.clear_table('payment_schedule');

        // Loop through child table rows in 'items' and fetch linked Purchase Order details
        let promises = frm.doc.items.map(item => {
            if (item.purchase_order) {
                // Fetch Purchase Order document
                return frappe.db.get_doc('Purchase Order', item.purchase_order).then(purchase_order => {
                    if (purchase_order.payment_schedule && purchase_order.payment_schedule.length > 0) {
                        purchase_order.payment_schedule.forEach(schedule => {
                            // Add rows to the Payment Schedule table in Purchase Invoice
                            let new_row = frm.add_child('payment_schedule', {
                                payment_term: schedule.payment_term,
                                due_date: schedule.due_date,
                                invoice_portion: schedule.invoice_portion,
                                payment_amount: schedule.payment_amount
                            });
                        });
                    }
                }).catch(err => {
                    console.error(`Error fetching Purchase Order: ${item.purchase_order}`, err);
                });
            }
        });

        // Wait for all fetch operations to complete, then refresh the Payment Schedule table
        Promise.all(promises).then(() => {
            frm.refresh_field('payment_schedule');
        });
    }
});

frappe.listview_settings["Attendance"] = {
	add_fields: ["status", "attendance_date"],

	get_indicator: function (doc) {
		if (["Present", "Work From Home"].includes(doc.status)) {
			return [__(doc.status), "green", "status,=," + doc.status];
		} else if (["Absent", "On Leave"].includes(doc.status)) {
			return [__(doc.status), "red", "status,=," + doc.status];
		} else if (doc.status == "Half Day") {
			return [__(doc.status), "orange", "status,=," + doc.status];
		}
	},

	onload: function (list_view) {
	    let me = this;
        if( frappe.user.has_role('HR User') || frappe.user.has_role('HR Manager') || frappe.user.has_role('System Manager') ){
		list_view.page.add_inner_button(__("Mark Attendance"), function () {
			let first_day_of_month = moment().startOf("month");

			if (moment().toDate().getDate() === 1) {
				first_day_of_month = first_day_of_month.subtract(1, "month");
			}

			let dialog = new frappe.ui.Dialog({
				title: __("Mark Attendance"),
				fields: [
					{
						fieldname: "employee",
						label: __("For Employee"),
						fieldtype: "Link",
						options: "Employee",
						get_query: () => {
							return {
								query: "erpnext.controllers.queries.employee_query",
							};
						},
						reqd: 1,
						onchange: () => me.reset_dialog(dialog),
					},
					{
						fieldtype: "Section Break",
						fieldname: "time_period_section",
						hidden: 1,
					},
					{
						label: __("Start"),
						fieldtype: "Date",
						fieldname: "from_date",
						reqd: 1,
						default: first_day_of_month.toDate(),
						onchange: () => me.get_unmarked_days(dialog),
					},
					{
						fieldtype: "Column Break",
						fieldname: "time_period_column",
					},
					{
						label: __("End"),
						fieldtype: "Date",
						fieldname: "to_date",
						reqd: 1,
						default: moment().subtract(1, "days").toDate(),
						onchange: () => me.get_unmarked_days(dialog),
					},
					{
						fieldtype: "Section Break",
						fieldname: "days_section",
						hidden: 1,
					},
					{
						label: __("Status"),
						fieldtype: "Select",
						fieldname: "status",
						options: ["Present", "Half Day"],
						reqd: 1,
					},
					{
						label: __("Exclude Holidays"),
						fieldtype: "Check",
						fieldname: "exclude_holidays",
						onchange: () => me.get_unmarked_days(dialog),
					},
					{
						label: __("Unmarked Attendance for days"),
						fieldname: "unmarked_days",
						fieldtype: "MultiCheck",
						options: [],
						columns: 2,
						select_all: true,
					},
				],
				primary_action(data) {
					if (cur_dialog.no_unmarked_days_left) {
						frappe.msgprint(
							__(
								"Attendance from {0} to {1} has already been marked for the Employee {2}",
								[data.from_date, data.to_date, data.employee],
							),
						);
					} else {
						frappe.confirm(
							__("Mark attendance as {0} for {1} on selected dates?", [
								data.status,
								data.employee,
							]),
							() => {
								frappe.call({
									method: "hrms.hr.doctype.attendance.attendance.mark_bulk_attendance",
									args: {
										data: data,
									},
									callback: function (r) {
										if (r.message === 1) {
											frappe.show_alert({
												message: __("Attendance Marked"),
												indicator: "blue",
											});
											cur_dialog.hide();
										}
									},
								});
							},
						);
					}
					dialog.hide();
					list_view.refresh();
				},
				primary_action_label: __("Mark Attendance"),
			});
			dialog.show();
		});
	}
	},

	reset_dialog: function (dialog) {
		let fields = dialog.fields_dict;

		dialog.set_df_property("time_period_section", "hidden", fields.employee.value ? 0 : 1);

		dialog.set_df_property("days_section", "hidden", 1);
		dialog.set_df_property("unmarked_days", "options", []);
		dialog.no_unmarked_days_left = false;
		fields.exclude_holidays.value = false;

		fields.to_date.datepicker.update({
			maxDate: moment().subtract(1, "days").toDate(),
		});

		this.get_unmarked_days(dialog);
	},

	get_unmarked_days: function (dialog) {
		let fields = dialog.fields_dict;
		if (fields.employee.value && fields.from_date.value && fields.to_date.value) {
			dialog.set_df_property("days_section", "hidden", 0);
			dialog.set_df_property("status", "hidden", 0);
			dialog.set_df_property("exclude_holidays", "hidden", 0);
			dialog.no_unmarked_days_left = false;

			frappe
				.call({
					method: "hrms.hr.doctype.attendance.attendance.get_unmarked_days",
					async: false,
					args: {
						employee: fields.employee.value,
						from_date: fields.from_date.value,
						to_date: fields.to_date.value,
						exclude_holidays: fields.exclude_holidays.value,
					},
				})
				.then((r) => {
					var options = [];

					for (var d in r.message) {
						var momentObj = moment(r.message[d], "YYYY-MM-DD");
						var date = momentObj.format("DD-MM-YYYY");
						options.push({
							label: date,
							value: r.message[d],
							checked: 1,
						});
					}

					dialog.set_df_property(
						"unmarked_days",
						"options",
						options.length > 0 ? options : [],
					);
					dialog.no_unmarked_days_left = options.length === 0;
				});
		}
	},
};

frappe.ui.form.on('Expense Claim', {
    onload: function(frm) {
        // Block 1: Auto-fill employee field if the user is not an Administrator and the employee field is empty
        if (frappe.session.user !== 'Administrator' && !frm.doc.employee) {
            // Make an API call to get the Employee linked with the current user
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Employee',
                    filters: { user_id: frappe.session.user },
                    fieldname: 'name'
                },
                callback: function(r) {
                    if (r.message && !frm.doc.employee) {
                        // If Employee record found and employee field is empty, set it in the Employee field
                        frm.set_value('employee', r.message.name);
                    }
                }
            });
        }

        // Block 2: Log and hide 'approval_status' field if the user doesn't have the 'Accounts Manager' role
        if (!frappe.user.has_role('Accounts Manager')) {
            console.log('User does not have the "Accounts Manager" role.');
            frm.set_df_property('approval_status', 'hidden', true);
        } else {
            console.log('User has the "Accounts Manager" role.');
        }
    },

    validate: function(frm) {
        // Set the posting_date to the expense_date of the first expense item
        $.each(frm.doc.expenses, function(i, d) {
            if (d.expense_date) {
                frm.set_value('posting_date', d.expense_date);
                console.log('Expense Date:', d.expense_date, 'Posting Date:', frm.doc.posting_date);
                return false;  // Break loop after setting from the first expense
            }
        });
    }
});

