/**
 * Insert Address and set primary_address on Customer if Billing
 */
function create_address(customer_name, values, address_type,
                        address_line1, address_line2,
                        city, state, country, pincode) {
    const address_doc = {
        doctype: 'Address',
        address_title: `${customer_name} ${address_type}`,
        address_line1,
        address_line2,
        city,
        state,
        country,
        pincode,
        links: [{ link_doctype: 'Customer', link_name: customer_name }],
        is_primary_address:  address_type === 'Billing'  ? 1 : 0,
        is_shipping_address: address_type === 'Shipping' ? 1 : 0,
        address_type
    };

    frappe.call({
        method: 'frappe.client.insert',
        args: { doc: address_doc },
        callback: function (res) {
            if (!res.exc && res.message) {
                const addr_name = res.message.name;
                frappe.msgprint(__(`${address_type} Address created: {0}`, [addr_name]));

                // Set Customer.primary_address field when Billing address is created
                if (address_type === 'Billing') {
                    frappe.call({
                        method: 'frappe.client.set_value',
                        args: {
                            doctype: 'Customer',
                            name: customer_name,
                            fieldname: 'customer_primary_address',
                            value: addr_name
                        },
                        callback: () => {
                            frappe.msgprint(__('Customer.primary_address set to {0}', [addr_name]));
                        }
                    });
                }
            }
        }
    });
}

