frappe.ui.form.on('Employee', {
    refresh:function(frm){
        toggle_child_table_access(frm);
    },
    validate: function(frm) {
        const table = frm.doc.custom_months_for_bonus || [];
        const fy_map = {};

        for (let row of table) {
            const start_date = row.start_date;
            const end_date = row.end_date;
            const month = row.month;

            // Check if all fields are filled
            if (!start_date || !end_date || !month) {
                frappe.throw(__('Each row in "Months for Bonus" must have Start Date, End Date, and Month filled.'));
            }

            // Derive fiscal year from calendar year of start_date
            const date = frappe.datetime.str_to_obj(start_date);
            const fiscal_year = `${date.getFullYear()}`;

            // Initialize fiscal year list if not present
            if (!fy_map[fiscal_year]) {
                fy_map[fiscal_year] = [];
            }

            // Check for duplicate month within the same fiscal year
            if (fy_map[fiscal_year].includes(month)) {
                frappe.throw(
                    __('Duplicate month "{0}" found for fiscal year "{1}" in "Months for Bonus".', [month, fiscal_year])
                );
            }

            fy_map[fiscal_year].push(month);

            // Limit to 2 months per fiscal year
            if (fy_map[fiscal_year].length > 2) {
                frappe.throw(
                    __('Only 2 bonus months allowed per fiscal year. Fiscal Year "{0}" has more.', [fiscal_year])
                );
            }
        }
    },

});

