frappe.ui.form.on("Timesheet", {
    validate: function(frm) {
        let today = frappe.datetime.get_today();
        if (frappe.user.has_role("HR Manager") || frappe.user.has_role("System Manager")) {
            return;
        }

        (frm.doc.time_logs || []).forEach(row => {
            // Only validate if row is newly added (row.name starts with "new-" before save)
            if (row.name && row.name.startsWith("new-")) {

                // Check From Date
                if (row.from_time) {
                    let from_date = frappe.datetime.str_to_obj(row.from_time);
                    let from_str = frappe.datetime.obj_to_str(from_date);

                    if (from_str < today) {
                        frappe.throw(__("Row {0}: From Time cannot be a past date.", [row.idx]));
                    }
                }

                // Check To Date
                if (row.to_time) {
                    let to_date = frappe.datetime.str_to_obj(row.to_time);
                    let to_str = frappe.datetime.obj_to_str(to_date);

                    if (to_str < today) {
                        frappe.throw(__("Row {0}: To Time cannot be a past date.", [row.idx]));
                    }
                }
            }
        });
    }
});
